from template_utils import (
    load_ideal_title_page,
    add_heading_1,
    add_heading_2,
    add_paragraph,
    add_toc,
    save_report
)


def generate() -> str:
    """
    Генерирует академический доклад по теме видов и классов автомобилей.
    """
    topic = "Виды и классы автомобилей: современная классификация, конструктивные типы и сегментация"
    discipline = "Автомобильный транспорт"

    # 1. Загрузка идеального титульного листа из эталонного шаблона
    doc = load_ideal_title_page(topic=topic, discipline=discipline)
    doc.add_page_break()

    # 2. Чистое автоматическое оглавление
    add_toc(doc)
    doc.add_page_break()

    # 3. ВВЕДЕНИЕ
    add_heading_1(doc, "Введение")
    add_paragraph(doc, "Современный автомобильный транспорт представляет собой невероятно широкую и многогранную индустрию. За более чем столетие эволюции автопрома сформировалась развитая система классификации транспортных средств, учитывающая их функциональное назначение, габаритные размеры, рабочий объем двигателя, тип кузова, характер силовой установки и целевую аудиторию.")
    add_paragraph(doc, "Актуальность темы обусловлена необходимостью четкой унификации и стандартизации автомобилей как для международной торговли и сертификации, так и для регулирования дорожного движения, налогообложения, страхования и потребительского выбора. В условиях стремительного размытия традиционных межсегментных границ и появления новых классов (кросс-купе, гибридов, электромобилей) систематизация знаний о видах и классах автотранспорта приобретает особую научную и практическую значимость.")
    add_paragraph(doc, "Объектом исследования является автомобильный транспорт как техническая и потребительская категория. Предметом исследования выступают принципы классификации, конструктивные особенности типы кузовов, европейская и международная сегментация автомобильного парка.")
    add_paragraph(doc, "Целью данной работы является комплексный анализ видов и классов автомобилей, определение их ключевых технико-эксплуатационных характеристик и исследование современных тенденций трансформации автоклассов.")
    add_paragraph(doc, "Для достижения поставленной цели в работе решены следующие задачи:")
    add_paragraph(doc, "1. Изучить классификацию автотранспортных средств по функциональному назначению и эксплуатационным свойствам.")
    add_paragraph(doc, "2. Проанализировать типологию автомобильных кузовов (одно-, двухобъемные и трехобъемные конструкции).")
    add_paragraph(doc, "3. Рассмотреть европейскую систему сегментации легковых автомобилей (UNECE), от A-класса до F-сегмента и специальных категорий.")
    add_paragraph(doc, "4. Классифицировать автомобили по видам применяемых силовых установок (ДВС, гибриды HEV/PHEV, электромобили BEV, водородные FCEV).")
    add_paragraph(doc, "5. Исследовать специфику классификации коммерческого транспорта, грузовых автомобилей и автобусов.")
    add_paragraph(doc, "Методологической основой исследования служат системно-аналитический подход, классификационный метод, сравнительный анализ нормативно-правовых актов и отраслевых стандартов (ГОСТ, стандарты ЕЭК ООН).")
    doc.add_page_break()

    # 4. ГЛАВА 1
    add_heading_1(doc, "Глава 1. Классификация автомобилей по назначению и типу кузова")
    add_heading_2(doc, "1.1 Классификация по функциональному назначению")
    add_paragraph(doc, "По своему базовому назначению весь автомобильный транспорт подразделяется на три основные группы:")
    add_paragraph(doc, "1. Пассажирский транспорт — предназначены для перевозки людей и их багажа (легковые автомобили емкостью до 8 мест плюс водитель, а также автобусы различных классов).")
    add_paragraph(doc, "2. Грузовой транспорт — предназначены для перевозки разнообразных грузов. Включают бортовые автомобили, фургоны, тягачи с полуприцепами, самосвалы и цистерны.")
    add_paragraph(doc, "3. Специальный и специализированный транспорт — снабжен стационарным оборудованием для выполнения конкретных технологических операций (автокраны, пожарные автомобили, скорая медицинская помощь, автоцистерны для опасных грузов, коммунальная техника).")

    add_heading_2(doc, "1.2 Классификация по типам кузова")
    add_paragraph(doc, "Кузов легкового автомобиля определяет его внешний вид, вместимость, аэродинамические качества и степень жесткости конструкции. По пространственной компоновке кузова подразделяются на трехобъемные (четко выделены моторный отсек, салон и багажник), двухобъемные (капот и совмещенный салон с багажником) и однообъемные (капот, салон и багажник представляют собой единый пространственный объем).")
    add_paragraph(doc, "К основным типам кузовов относятся:")
    add_paragraph(doc, "• Седан — трехобъемный кузов с четырьмя (реже двумя) дверями и изолированным багажным отделением. Является классическим типом кузова легкового автомобиля.")
    add_paragraph(doc, "• Хэтчбек — двухобъемный кузов с задней дверью, открывающей доступ в багажное отделение, совмещенное с салоном. Отличается компактными габаритами и практичностью.")
    add_paragraph(doc, "• Универсал — двухобъемный кузов с увеличенным багажным отделением и длинной крышей, продленной до задней двери.")
    add_paragraph(doc, "• Купе — трехобъемный или двухобъемный кузов с двумя дверями и спортивным силуэтом крыши, ориентированный на водителя и переднего пассажира.")
    add_paragraph(doc, "• Кабриолет и Родстер — кузовы со складывающейся мягкой или жесткой крышей для езды в открытом режиме.")
    add_paragraph(doc, "• Кроссовер (CUV) и Внедорожник (SUV) — кузовы увеличенной вместимости с повышенным дорожным просветом и высокой посадкой водителя. Внедорожники традиционно обладают рамной конструкцией и честным полным приводом, в то время как кроссоверы строятся на несущем кузове легковой платформы.")
    add_paragraph(doc, "• Минивэн — однообъемный или полутораобъемный кузов повышенной пассажировместимости (от 6 до 9 мест) с высокой крышей и широким трансформируемым салоном.")
    doc.add_page_break()

    # 5. ГЛАВА 2
    add_heading_1(doc, "Глава 2. Европейская система сегментации легковых автомобилей (UNECE)")
    add_heading_2(doc, "2.1 Особо малый и малый классы (Сегменты A, B)")
    add_paragraph(doc, "Наиболее распространенной и общепринятой в мировой практике является система сегментации Европейской комиссии (UNECE). Согласно этой классификации, автомобили делятся на буквы от A до F, а также отдельные специализированные группы.")
    add_paragraph(doc, "• Сегмент A (Microcars / City cars) — особо малый класс. Длина таких автомобилей обычно не превышает 3,7 метров. Предназначены для плотной городской застройки, отличаются высокой маневренностью и минимальным расходом топлива (примеры: Smart Fortwo, Fiat 500).")
    add_paragraph(doc, "• Сегмент B (Small cars / Subcompact) — малый класс. Длина кузова варьируется от 3,7 до 4,2 метров. Является одним из самых популярных классов в Европе и развивающихся странах благодаря балансу между экономичностью и комфортом (примеры: Volkswagen Polo, Renault Clio, Lada Granta).")

    add_heading_2(doc, "2.2 Компактный, средний и полноразмерный классы (Сегменты C, D, E)")
    add_paragraph(doc, "• Сегмент C (Medium cars / Compact class / «Гольф-класс») — компактный класс (длина 4,2–4,5 м). Является эталоном семейного городского автомобиля (примеры: Volkswagen Golf, Toyota Corolla, Ford Focus).")
    add_paragraph(doc, "• Сегмент D (Larger medium cars / Mid-size) — средний или семейный класс (длина 4,5–4,8 м). Предлагает высокий уровень комфорта, просторный задний ряд и мощные двигатели (примеры: Volkswagen Passat, Toyota Camry, BMW 3 Series).")
    add_paragraph(doc, "• Сегмент E (Executive cars / Full-size) — бизнес-класс (длина более 4,8 м). Характеризуется премиальными материалами отделки, высоким уровнем шумоизоляции и передовыми электронными системами (примеры: Mercedes-Benz E-Class, BMW 5 Series, Audi A6).")

    add_heading_2(doc, "2.3 Представительский класс, спортивные модели и внедорожники (Сегменты F, S, J, M)")
    add_paragraph(doc, "• Сегмент F (Luxury cars) — представительский или люксовый класс. Длина превышает 5,0 метров. Создаются для максимального комфорта пассажиров заднего ряда, часто эксплуатируются с наемным водителем (примеры: Mercedes-Benz S-Class, BMW 7 Series, Rolls-Royce Phantom).")
    add_paragraph(doc, "• Сегмент S (Sports coupes / Supercars) — спортивные купе, кабриолеты и суперкары с мощными силовыми установками и спортивной настройкой подвески (примеры: Porsche 911, Ferrari F8, Ford Mustang).")
    add_paragraph(doc, "• Сегмент J (Sports utility vehicles / SUV / Off-road) — кроссоверы и внедорожники всех размеров, от компактных паркетников до полноразмерных рамных моделей.")
    add_paragraph(doc, "• Сегмент M (Multi-purpose cars / MPV) — минивэны и компактвэны для больших семей и коммерческих перевозок.")
    doc.add_page_break()

    # 6. ГЛАВА 3
    add_heading_1(doc, "Глава 3. Классификация по типу силовой установки и технологии привода")
    add_heading_2(doc, "3.1 Традиционные автомобили с ДВС")
    add_paragraph(doc, "Традиционная классификация опирается на тип применяемого теплового двигателя:")
    add_paragraph(doc, "• Бензиновые автомобили — работают на легких фракциях нефти по циклу Отто или Миллера. Характеризуются высокой оборотистостью и относительной простотой системы нейтрализации выхлопа.")
    add_paragraph(doc, "• Дизельные автомобили — работают по циклу Дизеля на тяжелом топливе. Отличаются повышенным крутящим моментом на низких оборотах и высоким термическим КПД.")
    add_paragraph(doc, "• Газобаллонные автомобили (LPG / CNG) — используют сжиженный нефтяной (пропан-бутан) или сжатый природный (метан) газ в качестве экологичной альтернативы жидким углеводородам.")

    add_heading_2(doc, "3.2 Электрифицированные и полностью электрические транспортные средства")
    add_paragraph(doc, "Глобальный экологический тренд сформировал новую классификацию транспортных средств по степени электрификации:")
    add_paragraph(doc, "• MHEV (Mild Hybrid Electric Vehicle) — «мягкий» гибрид с стартер-генератором (48V), помогающим ДВС при разгоне.")
    add_paragraph(doc, "• HEV (Hybrid Electric Vehicle) — классический гибрид, способный передвигаться на чистой электротяге на короткие расстояния без возможности зарядки от внешней сети.")
    add_paragraph(doc, "• PHEV (Plug-in Hybrid Electric Vehicle) — подключаемый гибрид с батареей увеличенной емкости, заряжаемый от розетки.")
    add_paragraph(doc, "• BEV (Battery Electric Vehicle) — аккумуляторный электромобиль, полностью лишенный ДВС (примеры: Tesla Model 3, Zeekr 001).")
    add_paragraph(doc, "• FCEV (Fuel Cell Electric Vehicle) — водородный электромобиль на топливных элементах, где электричество вырабатывается в результате химической реакции водорода и кислорода (пример: Toyota Mirai).")
    doc.add_page_break()

    # 7. ГЛАВА 4
    add_heading_1(doc, "Глава 4. Грузовые автомобили, автобусы и спецтехника")
    add_heading_2(doc, "4.1 Классификация грузовых автомобилей")
    add_paragraph(doc, "Грузовые автомобили классифицируются по полной массе и грузоподъемности:")
    add_paragraph(doc, "• Особо малые (LCV — Light Commercial Vehicles) — полная масса до 3,5 тонн (примеры: ГАЗель, Volkswagen Transporter). Позволяют управлять водителям с категорией «B».")
    add_paragraph(doc, "• Среднетоннажные — полная масса от 3,5 до 12 тонн (примеры: ГАЗон NEXT, MAN TGL).")
    add_paragraph(doc, "• Крупнотоннажные — полная масса свыше 12 тонн. Включают магистральные седельные тягачи с полуприцепами для международной логистики и карьерные самосвалы.")

    add_heading_2(doc, "4.2 Классификация автобусов")
    add_paragraph(doc, "Автобусы систематизируются по габаритной длине и функциональному назначению:")
    add_paragraph(doc, "• По длине: особо малые (до 5 м), малые (6–7,5 м), средние (8–9,5 м), большие (10,5–12 м) и особо большие сочлененные («гармошки», 16,5–24 м).")
    add_paragraph(doc, "• По назначению: городского типа (с низким полом и широкими площадками), пригородные, междугородные и туристические (лайнеры повышенной комфортности с багажными отсеками).")
    doc.add_page_break()

    # 8. ЗАКЛЮЧЕНИЕ
    add_heading_1(doc, "Заключение")
    add_paragraph(doc, "На основе проведенного исследования видов и классов автомобилей сделаны следующие выводы:")
    add_paragraph(doc, "1. Современная система классификации автомобилей является многокритериальной и включает в себя разделение по функциональному назначению, типам кузова, размерным сегментам и типу применяемой энергии.")
    add_paragraph(doc, "2. Европейская классификация UNECE (от A до F сегментов, а также S, J, M) выступает общепринятым международным ориентиром для маркетинговой и технической сегментации легковых автомобилей.")
    add_paragraph(doc, "3. Происходит интенсивная диффузия типов кузова: традиционные седаны и хэтчбеки вытесняются кроссоверами (CUV) и купеобразными кроссоверами (кросс-купе), объединяющими проходимость и спортивный дизайн.")
    add_paragraph(doc, "4. Главным вектором трансформации классификации автомобилей в XXI веке является переход от классических ДВС к гибридным (PHEV) и полностью электрическим (BEV/FCEV) сиповым установкам, что влечет за собой пересмотр стандартов технического обслуживания и требований к дорожной инфраструктуре.")
    doc.add_page_break()

    # 9. СПИСОК ЛИТЕРАТУРЫ
    add_heading_1(doc, "Список использованных информационных источников")
    add_paragraph(doc, "1. Вахламов, В. К. Конструкция, теория и расчет автомобилей : учебник для вузов / В. К. Вахламов. — 4-е изд. — М. : Академия, 2020. — 480 с.")
    add_paragraph(doc, "2. Горев, А. Э. Грузовые автомобильные перевозки : учебное пособие для вузов / А. Э. Горев. — 7-е изд. — М. : Академия, 2018. — 304 с.")
    add_paragraph(doc, "3. ГОСТ 31286-2005. Транспортные средства. Классификация и термины. — М. : Стандартинформ, 2006. — 18 с.")
    add_paragraph(doc, "4. Нагайцев, М. В. Электромобили и гибридные автомобили : учебное пособие / М. В. Нагайцев, В. В. Селифонов. — М. : МГТУ им. Н. Э. Баумана, 2021. — 216 с.")
    add_paragraph(doc, "5. Туревский, И. С. Теория и конструкция автомобилей : учебник / И. С. Туревский. — М. : ИНФРА-М, 2022. — 392 с.")
    add_paragraph(doc, "6. UNECE. Consolidated Resolution on the Construction of Vehicles (R.E.3) / United Nations Economic Commission for Europe. — Geneva : UN, 2021. — 114 p.")
    add_paragraph(doc, "7. Reimpell, J. The Automotive Chassis: Engineering Principles / J. Reimpell, H. Stoll, J. Betzler. — 2nd ed. — Oxford : Butterworth-Heinemann, 2001. — 456 p.")

    output_filename = "Доклад_Виды_и_классы_автомобилей.docx"
    return save_report(doc, output_filename)


if __name__ == "__main__":
    generate()
